import { test, expect } from '@playwright/test';

test.describe('Recently Searched Terms Suggestions', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display recently searched terms as suggestions when user starts typing', async ({ page }) => {
    // Verify search input is visible
    const searchInput = page.getByPlaceholder('Search...');
    await expect(searchInput).toBeVisible();

    // Type the first character
    await searchInput.fill('a');

    // Wait for suggestions to load
    await page.waitForResponse(response => 
      response.url().includes('/api/search/suggestions') && response.status() === 200
    );

    // Verify suggestions container is visible
    const suggestionsContainer = page.getByRole('region', { name: /suggestions/i });
    await expect(suggestionsContainer).toBeVisible();

    // Verify suggestions list is visible
    const suggestionsList = page.getByRole('list');
    await expect(suggestionsList).toBeVisible();

    // Verify at least one suggestion is displayed
    const suggestionsItems = page.getByRole('listitem');
    await expect(suggestionsItems).toHaveCount(1);

    // Verify suggestion text is displayed
    const suggestionText = page.getByText('apple');
    await expect(suggestionText).toBeVisible();

    // Click on a suggestion
    await suggestionText.click();

    // Verify search input is populated with the selected suggestion
    await expect(searchInput).toHaveValue('apple');

    // Verify search results page is displayed
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();
  });

  test('should handle no recent searches and display appropriate message', async ({ page }) => {
    // Clear any existing search history
    await page.route('**/api/search/suggestions', route => {
      route.abort();
    });

    // Type a character
    const searchInput = page.getByPlaceholder('Search...');
    await searchInput.fill('z');

    // Wait for API call to fail or timeout
    await page.waitForTimeout(500);

    // Verify suggestions container is visible but empty
    const suggestionsContainer = page.getByRole('region', { name: /suggestions/i });
    await expect(suggestionsContainer).toBeVisible();

    // Verify no suggestions list is present
    const suggestionsList = page.getByRole('list');
    await expect(suggestionsList).not.toBeVisible();

    // Verify no suggestion items exist
    const suggestionsItems = page.getByRole('listitem');
    await expect(suggestionsItems).toHaveCount(0);

    // Verify "No recent searches" message is displayed
    const noSuggestionsMessage = page.getByText('No recent searches');
    await expect(noSuggestionsMessage).toBeVisible();

    // Verify search input is still available for manual entry
    await expect(searchInput).toBeVisible();
  });
});
